css:
/* 挂接点示例用的样式：包自己带样式，不改基础界面 */
.hook-demo-badge {
  font-size: 9px;
  color: var(--dim);
  border: 1px solid var(--line);
  border-radius: 7px;
  padding: 0 5px;
  margin-left: 4px;
}
.hook-demo-chip {
  font-size: 10px;
  color: var(--accent);
  margin-left: 10px;
}

/* 面板里的按钮：包自带样式，不碰基础界面 */
.demo-btn {
  display: block; width: 100%; margin: 4px 0; padding: 8px 10px;
  font: inherit; font-size: 12px;
  background: var(--card); color: var(--accent);
  border: 1px solid var(--line-strong); border-radius: 8px;
  cursor: pointer;
}
.demo-btn:hover { background: var(--accent-soft); border-color: var(--accent); }
.demo-btn.ghost { color: var(--dim); }
.demo-out { font-size: 11px; color: var(--dim); margin-top: 4px; min-height: 1em; }

panels.script:
document.getElementById('demo-count').addEventListener('click', () => {
  const n = document.querySelectorAll('.sess').length;
  const turns = document.querySelectorAll('#stream .turn').length;
  const out = document.createElement('span');
  out.textContent = n + '/' + turns;
  document.getElementById('demo-count').replaceWith(out);
});

chart.script:
// 自定义面板类型 "chart"。
// 包定义了"什么是一种图表面板"，别的面板只要写 "type": "chart" 就能用，
// 不用每次都带一份自己的渲染代码。这与 Patchouli 的 pageTypes 注册表同形。
const canvas = document.createElement("canvas");
canvas.width = Math.min(host.clientWidth || 260, 320);
canvas.height = 120;
canvas.style.width = "100%";
host.replaceChildren(canvas);

const ctx = canvas.getContext("2d");
if (!ctx) {
  host.textContent = "no canvas";
  return;
}
const values = Array.isArray(data) ? data : [];
if (values.length === 0) {
  host.textContent = "no data";
  return;
}
const max = Math.max(...values.map((v) => Number(v) || 0), 1);
const gap = 6;
const barW = (canvas.width - gap * (values.length + 1)) / values.length;
const style = getComputedStyle(document.documentElement);
const accent = style.getPropertyValue("--accent").trim() || "#b4632a";
const dim = style.getPropertyValue("--dim").trim() || "#7d7264";

ctx.font = "10px system-ui";
values.forEach((v, i) => {
  const n = Number(v) || 0;
  const h = Math.max(2, Math.round((n / max) * (canvas.height - 24)));
  const x = gap + i * (barW + gap);
  const y = canvas.height - h - 14;
  ctx.fillStyle = accent;
  ctx.fillRect(x, y, barW, h);
  ctx.fillStyle = dim;
  ctx.fillText(String(n), x, canvas.height - 3);
});
